"""A deliberately varied, runnable Java practice curriculum.

Every drill is a complete ``public class Main`` program and has five independent
stdin/stdout fixtures (the first two are public).  Keeping this catalogue apart
from the original multi-language seed bank makes it easy to audit that these are
real coding problems rather than renamed copies of warm-ups.
"""
from __future__ import annotations


STARTER = '''import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // Read stdin, solve the exercise, and print only the requested result.
    }
}
'''


def _program(body: str) -> str:
    main_body, marker, helpers = body.partition("\n// HELPERS\n")
    return "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        Scanner in = new Scanner(new BufferedInputStream(System.in));\n" + main_body + "\n    }\n" + (helpers + "\n" if marker else "") + "}\n"


def _drill(key: str, title: str, difficulty: str, topics: list[str], description: str,
           constraints: list[str], body: str, cases: list[tuple[str, str]],
           complexity: str, hints: list[str]) -> dict:
    assert len(cases) >= 5
    tests = [{"input": source, "expected_output": expected} for source, expected in cases]
    # Medium and Hard records get an additional judge invocation with harmless
    # trailing whitespace.  This catches brittle token readers while retaining
    # five semantic edge cases instead of exposing a disguised duplicate.
    hidden = tests[2:]
    if difficulty in {"Medium", "Hard"} and len(hidden) < 4:
        frame = dict(tests[-1])
        frame["input"] += "\n"
        hidden.append(frame)
    return {"id": key, "title": title, "language": "java", "difficulty": difficulty,
            "topics": topics, "practice_frequency": "Common", "description": description,
            "constraints": constraints, "examples": [{"input": cases[0][0], "output": cases[0][1]}],
            "starter_code": STARTER, "solution": _program(body), "hints": hints,
            "expected_complexity": complexity, "public_tests": tests[:2], "hidden_tests": hidden}


