_drill("java-int-reorganize-possible", "Reorganize String Possible", "Medium", ["strings", "heaps", "greedy"], "Read a lowercase token. Print yes if its characters can be rearranged so adjacent characters differ, otherwise no.", ["0 <= length <= 200,000", "Input uses lowercase English letters."], "        String s=in.hasNext()?in.next():\"\";int[]f=new int[26];int mx=0;for(char c:s.toCharArray()){f[c-'a']++;mx=Math.max(mx,f[c-'a']);}System.out.println(mx<=(s.length()+1)/2?\"yes\":\"no\");", [("aab\n","yes"),("aaab\n","no"),("a\n","yes"),("\n","yes"),("vvvlo\n","yes")], "O(n) time, O(1) space", ["Only the largest frequency determines feasibility.", "It must fit into alternating positions.", "The threshold is ceil(n/2)."]),
_drill("java-int-reverse-linked-list", "Reverse Linked List Values", "Easy", ["linked-lists", "stacks"], "Given n node values in list order, print them in reversed order, space separated.", ["0 <= n <= 200,000"], "        int n=in.nextInt();Deque<Integer>s=new ArrayDeque<>();for(int i=0;i<n;i++)s.push(in.nextInt());boolean first=true;while(!s.isEmpty()){if(!first)System.out.print(\" \");System.out.print(s.pop());first=false;}System.out.println();", [("4\n1 2 3 4\n","4 3 2 1"),("0\n",""),("1\n8\n","8"),("3\n-1 0 1\n","1 0 -1"),("2\n7 7\n","7 7")], "O(n) time, O(n) space", ["A stack reverses the traversal order.", "Push values as they arrive.", "Pop them for the requested output."]),
_drill("java-int-lru-simulation", "LRU Cache Simulation", "Hard", ["maps", "linked-lists", "design"], "Process capacity c and q commands: put key value, get key. Print each get result; a missing key prints -1. Evict the least recently used key when full.", ["1 <= c <= 10,000", "1 <= q <= 100,000"], "        int cap=in.nextInt(),q=in.nextInt();LinkedHashMap<Integer,Integer>m=new LinkedHashMap<>(16,.75f,true);for(int i=0;i<q;i++){String op=in.next();int k=in.nextInt();if(op.equals(\"get\"))System.out.println(m.getOrDefault(k,-1));else{int v=in.nextInt();m.put(k,v);if(m.size()>cap)m.remove(m.keySet().iterator().next());}}", [("2 6\nput 1 1\nput 2 2\nget 1\nput 3 3\nget 2\nget 3\n","1\n-1\n3"),("1 4\nput 2 5\nget 2\nput 3 6\nget 2\n","5\n-1"),("2 3\nget 1\nput 1 9\nget 1\n","-1\n9"),("2 5\nput 1 1\nput 2 2\nget 1\nput 3 3\nget 1\n","1\n1"),("1 3\nput 1 1\nput 1 2\nget 1\n","2")], "O(1) expected per command, O(c) space", ["Access-order LinkedHashMap tracks recency.", "Reading a key must update recency too.", "The first key is least recently used."]),
